import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-inclusive-gateway-forkjoin/NotificationFanout.bpmn')
root = tree.getroot()
NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
}
errors = []

# 1. Root is definitions with BPMN namespace
tag = root.tag
assert 'definitions' in tag and 'BPMN' in tag, 'Root is not definitions'

# 2. One BPMNDiagram
diagrams = root.findall('bpmndi:BPMNDiagram', NS)
assert len(diagrams) == 1, f'Expected 1 BPMNDiagram, got {len(diagrams)}'

plane = diagrams[0].find('bpmndi:BPMNPlane', NS)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', NS)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', NS)}

# Collect all process elements and flows
proc = root.find('bpmn:process', NS)
all_ids = {}
flow_nodes = {}
seq_flows = {}

for child in proc:
    lt = child.tag.split('}')[1] if '}' in child.tag else child.tag
    cid = child.get('id')
    if not cid: continue
    if lt == 'sequenceFlow':
        seq_flows[cid] = (child.get('sourceRef'), child.get('targetRef'))
    elif lt != 'extensionElements':
        flow_nodes[cid] = lt
    all_ids[cid] = lt

# 2b. Shape per node, edge per flow
for nid in flow_nodes:
    if nid not in shapes:
        errors.append(f'MISSING SHAPE: {nid}')
for fid in seq_flows:
    if fid not in edges:
        errors.append(f'MISSING EDGE: {fid}')

# 3. All refs resolve
for fid, (src, tgt) in seq_flows.items():
    if src not in flow_nodes: errors.append(f'Unresolved sourceRef {src} in {fid}')
    if tgt not in flow_nodes: errors.append(f'Unresolved targetRef {tgt} in {fid}')

# 4. XOR gateways: conditions on non-default, exactly one default
for child in proc.findall('bpmn:exclusiveGateway', NS):
    outs = [f for f in child.findall('bpmn:outgoing', NS)]
    default = child.get('default')
    if not default:
        errors.append(f'XOR {child.get(\"id\")} has no default')

# 5. No activity/event has more than one incoming flow
incoming_count = {}
for child in proc:
    lt = child.tag.split('}')[1] if '}' in child.tag else child.tag
    if lt in ('extensionElements','sequenceFlow'): continue
    for inc in child.findall('bpmn:incoming', NS):
        cid = child.get('id')
        incoming_count[cid] = incoming_count.get(cid, 0) + 1

for nid, cnt in incoming_count.items():
    lt = flow_nodes.get(nid,'')
    if lt not in ('inclusiveGateway','parallelGateway','exclusiveGateway','complexGateway') and cnt > 1:
        errors.append(f'FAKE_JOIN: {nid} ({lt}) has {cnt} incoming flows')

# 5b. Inclusive join gateways must have multiple incoming
inc_gws = [c for c in proc if 'inclusiveGateway' in c.tag]
for gw in inc_gws:
    gid = gw.get('id')
    ins = gw.findall('bpmn:incoming', NS)
    outs = gw.findall('bpmn:outgoing', NS)
    # Validate not superfluous (1-in 1-out)
    if len(ins) == 1 and len(outs) == 1:
        errors.append(f'SUPERFLUOUS_GATEWAY: {gid}')

# 6. Conditioned outgoing flows on inclusive split
split_gw = proc.find('bpmn:inclusiveGateway[@id=\"Gw_Split\"]', NS)
for fid in [e.text for e in split_gw.findall('bpmn:outgoing', NS)]:
    sf = proc.find(f'bpmn:sequenceFlow[@id=\"{fid}\"]', NS)
    cond = sf.find('bpmn:conditionExpression', NS) if sf is not None else None
    if cond is None:
        errors.append(f'MISSING_CONDITION on split outgoing flow {fid}')

if errors:
    for e in errors: print('ERROR:', e)
else:
    print('VALID - all structural checks passed')
    print(f'  Nodes: {list(flow_nodes.keys())}')
    print(f'  Flows: {list(seq_flows.keys())}')
    print(f'  Shapes: {len(shapes)}, Edges: {len(edges)}')
